  const iso = (date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
  const dayAgo = (n) => { const d = new Date(); d.setDate(d.getDate() - n); return iso(d); };
  const monthAgo = (n, day = 14) => { const d = new Date(); d.setMonth(d.getMonth() - n, 1); d.setDate(Math.min(day, new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate())); return iso(d); };
  const currency = (amount) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(amount || 0);
  const compactCurrency = (amount) => {
    const a = Math.abs(amount || 0);
    const id=state?.language==='id';
    if (a >= 1_000_000_000) return `Rp ${(amount / 1_000_000_000).toFixed(1).replace('.', id?',':'.')} ${id?'M':'B'}`;
    if (a >= 1_000_000) return `Rp ${(amount / 1_000_000).toFixed(2).replace('.', id?',':'.')} ${id?'jt':'M'}`;
    if (a >= 1000) return `Rp ${(amount / 1000).toFixed(0)} ${id?'rb':'K'}`;
    return currency(amount);
  };
